import json
with open('submissions.before.json') as f: before_data = json.load(f)
with open('submissions.after.json') as f: after_data = json.load(f)
print('before type:', type(before_data).__name__, 'len:', len(before_data) if isinstance(before_data, list) else 'N/A')
print('after type:', type(after_data).__name__, 'len:', len(after_data) if isinstance(after_data, list) else 'N/A')
if isinstance(before_data, list) and isinstance(after_data, list):
    before_ids = {s.get('id') for s in before_data}
    after_ids = {s.get('id') for s in after_data}
    new_ids = after_ids - before_ids
    print('new submissions:', len(new_ids))
    for s in after_data:
        if s.get('id') in new_ids:
            print(json.dumps({k:v for k,v in s.items() if k in ['id','tx_task_id','normalized_score','created_at','request_id','checks']}, indent=2))
